<?php

namespace Zero\Tests\Core;

use Zero\Core\Application;

/**
 * Time-based session regeneration: when a session is old enough for a new id,
 * and where the interval comes from. The check runs from defineConstants(),
 * after the .ini files are read; in the constructor the constant was never
 * defined and no session was regenerated by age.
 */
class SessionRegenerateTest extends ZeroTestCase
{
    public function testSessionYoungerThanTheIntervalIsNotAged(): void
    {
        $this->assertFalse(Application::sessionIsAged(1000, 1000 + 1800, 1800));
    }

    public function testSessionOlderThanTheIntervalIsAged(): void
    {
        $this->assertTrue(Application::sessionIsAged(1000, 1000 + 1801, 1800));
    }

    public function testAnIntervalOfZeroNeverAges(): void
    {
        $this->assertFalse(Application::sessionIsAged(0, PHP_INT_MAX, 0));
    }

    /**
     * PHPUnit does not run defineConstants(), so the constant is undefined
     * here: a site that left the key out of its config.
     */
    public function testIntervalDefaultsWhenTheConstantIsUndefined(): void
    {
        $this->assertFalse(defined('SESSION_REGENERATE_INTERVAL'), 'this test needs the constant undefined');
        $this->assertSame(Application::SESSION_REGENERATE_DEFAULT, Application::sessionRegenerateInterval());
        $this->assertSame(1800, Application::SESSION_REGENERATE_DEFAULT);
    }

    public function testRegenerationRunsFromDefineConstantsNotTheConstructor(): void
    {
        $source = file_get_contents(dirname(__DIR__) . '/Application.php');

        $constructor = substr($source, strpos($source, 'public function __construct()'), 900);
        $this->assertStringNotContainsString('session_regenerate_id', $constructor);

        $define = substr($source, strpos($source, 'public function defineConstants('));
        $define = substr($define, 0, strpos($define, 'public function parseRequest('));
        $this->assertStringContainsString('$this->regenerateAgedSession()', $define);
    }

    public function testTheSkeletonConfigCarriesTheInterval(): void
    {
        foreach (['skeleton/config/constants.ini', 'skeleton/config-templates/constants.ini'] as $file) {
            $keys = parse_ini_file(dirname(__DIR__) . '/' . $file, false, INI_SCANNER_RAW);
            $this->assertSame('1800', $keys['SESSION_REGENERATE_INTERVAL'] ?? null, $file);
        }
    }
}
